#[cfg(test)]
mod tests {
    use super::*;

    /// Phase 2.1 — table-length sanity guard against accidental data loss on
    /// re-generation (extract_bidi.py).
    #[test]
    fn tables_have_expected_size() {
        assert_eq!(LATIN1_BIDI_TYPES.len(), 256, "latin1 must cover U+0000..U+00FF");
        assert_eq!(NON_LATIN1_BIDI_RANGES.len(), 714, "ranges count must match pretext");
        // Ranges must be sorted by start (binary search invariant).
        for i in 1..NON_LATIN1_BIDI_RANGES.len() {
            assert!(
                NON_LATIN1_BIDI_RANGES[i].0 >= NON_LATIN1_BIDI_RANGES[i - 1].1 + 1,
                "range [{:#x}..{:#x}] overlaps previous [{:#x}..{:#x}]",
                NON_LATIN1_BIDI_RANGES[i].0, NON_LATIN1_BIDI_RANGES[i].1,
                NON_LATIN1_BIDI_RANGES[i - 1].0, NON_LATIN1_BIDI_RANGES[i - 1].1,
            );
        }
    }

    /// Spot samples extracted from pretext `bidi-data.ts` — any drift here
    /// means the table was regenerated against a different Unicode version.
    #[test]
    fn latin1_samples_match_pretext() {
        // U+0041 'A'调主体新生 = L
        assert_eq!(LATIN1_BIDI_TYPES[0x41], BidiType::L);
        // U+005B '[' punctuation = On (pretext: 'ON').
        assert_eq!(LATIN1_BIDI_TYPES[0x5B], BidiType::On);
        // U+0030 '0' digit = En (pretext: 'EN' — European number).
        assert_eq!(LATIN1_BIDI_TYPES[0x30], BidiType::En);
        // U+0020 space = Ws.
        assert_eq!(LATIN1_BIDI_TYPES[0x20], BidiType::Ws);
        // U+00B0 degree sign — default neutral.
        assert_eq!(LATIN1_BIDI_TYPES[0xB0], BidiType::Et);
    }

    /// Non-Latin1: well-known strong RTL scripts must map to their canonical class.
    #[test]
    fn non_latin1_strong_rtl_samples() {
        // Hebrew letter Aleph U+05D0 = R (RTL strong).
        let he = NON_LATIN1_BIDI_RANGES.iter().find(|(s, e, _)| *s <= 0x05D0 && 0x05D0 <= *e);
        assert!(he.is_some(), "Hebrew aleph U+05D0 must be covered");
        assert_eq!(he.unwrap().2, BidiType::R);
        // Arabic letter U+0627 = Al (Arabic letter strong).
        let ar = NON_LATIN1_BIDI_RANGES.iter().find(|(s, e, _)| *s <= 0x0627 && 0x0627 <= *e);
        assert!(ar.is_some(), "Arabic alef U+0627 must be covered");
        assert_eq!(ar.unwrap().2, BidiType::Al);
    }
}
